		return aluPeakProbeReps, nil
	}
	reps := aluPeakTargetNs / nsPerRep
	if reps < aluPeakProbeReps {
		reps = aluPeakProbeReps
	}
	if reps > aluPeakMaxReps {
		reps = aluPeakMaxReps
	}
